begin;
create table public.sign_envelopes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),brokerage_id uuid references public.brokerages(id),deal_id uuid references public.deal_files(id),title text not null default 'Untitled signing request',message text not null default '',revision integer not null default 0,status text not null default 'Draft' check(status in ('Draft','Sent','Completing','Completed','Declined','Voided')),sequential boolean not null default true,expires_at timestamptz not null default now()+interval '14 days',source_path text not null default '',prepared_path text,final_path text,certificate_path text,source_sha256 text,prepared_sha256 text,final_sha256 text,fields jsonb not null default '[]',draft_recipients jsonb not null default '[]',sender_email text,documents jsonb not null default '[]',created_at timestamptz not null default now(),sent_at timestamptz,completed_at timestamptz,void_reason text);
alter table public.sign_envelopes add constraint sign_title_length check(length(trim(title)) between 1 and 200),add constraint sign_message_length check(length(message)<=5000),add constraint sign_field_count check(jsonb_typeof(fields)='array' and jsonb_array_length(fields)<=500),add constraint sign_draft_recipient_count check(jsonb_typeof(draft_recipients)='array' and jsonb_array_length(draft_recipients)<=20);
create index on public.sign_envelopes(user_id,created_at);
create table public.sign_recipients(id uuid primary key default gen_random_uuid(),envelope_id uuid not null references public.sign_envelopes(id),name text not null,email text not null,signing_order integer not null check(signing_order>0),status text not null default 'Waiting' check(status in ('Waiting','Invited','Viewed','Signed','Declined')),token_hash text unique,invited_at timestamptz,invitation_error text,session_hash text,session_expires_at timestamptz,otp_hash text,otp_expires_at timestamptz,otp_attempts integer not null default 0,otp_sent_at timestamptz,otp_window_start timestamptz,otp_send_count integer not null default 0,verified_at timestamptz,signed_at timestamptz,legal_name text,values jsonb,consent_text text,ip_address text,user_agent text,decline_reason text,unique(envelope_id,signing_order));
create table public.sign_events(id bigint generated always as identity primary key,envelope_id uuid not null references public.sign_envelopes(id),recipient_id uuid references public.sign_recipients(id),event text not null,actor_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now());
create table public.sign_completed_deliveries(envelope_id uuid not null references public.sign_envelopes(id),email text not null,created_at timestamptz not null default now(),accepted_at timestamptz,provider_id text,error text,primary key(envelope_id,email));
alter table public.sign_completed_deliveries enable row level security;
create function public.can_manage_sign_envelope(e public.sign_envelopes) returns boolean language sql stable set search_path='' as $$select (e.user_id=auth.uid() and (e.brokerage_id is null or e.brokerage_id=public.current_brokerage())) or public.is_brokerage_admin(e.brokerage_id)$$;
alter table public.sign_envelopes enable row level security;alter table public.sign_recipients enable row level security;alter table public.sign_events enable row level security;
create policy sign_owner_read on public.sign_envelopes for select to authenticated using(public.can_manage_sign_envelope(sign_envelopes));
create policy sign_owner_insert on public.sign_envelopes for insert to authenticated with check(user_id=auth.uid() and status='Draft' and prepared_path is null and final_path is null and source_sha256 is null and final_sha256 is null and completed_at is null and sent_at is null);
create policy sign_owner_update on public.sign_envelopes for update to authenticated using(public.can_manage_sign_envelope(sign_envelopes) and status='Draft') with check(public.can_manage_sign_envelope(sign_envelopes) and status='Draft');
create policy sign_recipient_read on public.sign_recipients for select to authenticated using(exists(select 1 from public.sign_envelopes e where e.id=envelope_id));
create policy sign_event_read on public.sign_events for select to authenticated using(exists(select 1 from public.sign_envelopes e where e.id=envelope_id));
grant select,insert,update on public.sign_envelopes to authenticated;
-- Sensitive credentials stay server-side, including hashes/OTP/session data.
grant select(id,envelope_id,name,email,signing_order,status,invited_at,invitation_error,verified_at,signed_at,legal_name,decline_reason) on public.sign_recipients to authenticated;
grant select on public.sign_events to authenticated;
create function public.guard_sign_envelope() returns trigger language plpgsql set search_path='' as $$begin
 if current_user in ('authenticated','anon') then
 if TG_OP='INSERT' then new.brokerage_id=public.current_brokerage();new.created_at=now();new.revision=0;new.sender_email=null;new.prepared_path=null;new.certificate_path=null;new.prepared_sha256=null;new.void_reason=null;
 else new.revision=old.revision+1;if old.status<>'Draft' or new.status<>'Draft' then raise exception 'Sent signing requests are locked';end if;
 if new.id<>old.id or new.created_at is distinct from old.created_at or new.sender_email is distinct from old.sender_email or new.user_id<>old.user_id or new.brokerage_id is distinct from old.brokerage_id or new.prepared_path is distinct from old.prepared_path or new.final_path is distinct from old.final_path or new.certificate_path is distinct from old.certificate_path or new.source_sha256 is distinct from old.source_sha256 or new.prepared_sha256 is distinct from old.prepared_sha256 or new.final_sha256 is distinct from old.final_sha256 or new.sent_at is distinct from old.sent_at or new.completed_at is distinct from old.completed_at then raise exception 'Server-managed signing data cannot be changed';end if;end if;
 if new.deal_id is not null and not exists(select 1 from public.deal_files d where d.id=new.deal_id and (d.user_id=auth.uid() or public.is_brokerage_admin(d.brokerage_id)) and d.brokerage_id is not distinct from new.brokerage_id) then raise exception 'Choose a transaction accessible in this brokerage';end if;
 if new.source_path<>'' and new.source_path not like new.user_id::text||'/'||new.id::text||'/%' then raise exception 'Document must belong to this request';end if;
 end if;return new;end $$;
create trigger guard_sign_envelope before insert or update on public.sign_envelopes for each row execute function public.guard_sign_envelope();
create function public.sign_begin_send(envelope uuid,source_hash text,prepared_file text,prepared_hash text,from_email text,signers jsonb,expected_revision integer) returns boolean language plpgsql security definer set search_path='' as $$declare e public.sign_envelopes;r jsonb;begin
 select * into e from public.sign_envelopes where id=envelope for update;if not found or e.status<>'Draft' or e.revision<>expected_revision then return false;end if;
 if e.expires_at<=now() then raise exception 'Choose a future expiry date';end if;
 for r in select value from jsonb_array_elements(signers) loop insert into public.sign_recipients(id,envelope_id,name,email,signing_order) values((r->>'id')::uuid,e.id,r->>'name',lower(r->>'email'),(r->>'order')::integer);end loop;
 update public.sign_envelopes set status='Sent',source_sha256=source_hash,prepared_path=prepared_file,prepared_sha256=prepared_hash,sender_email=from_email,sent_at=now() where id=e.id;
 insert into public.sign_events(envelope_id,event,details) values(e.id,'Sent',jsonb_build_object('source_sha256',source_hash,'prepared_sha256',prepared_hash,'fields',e.fields));return true;end $$;
create function public.sign_claim_invitation(recipient uuid,new_token text) returns boolean language plpgsql security definer set search_path='' as $$declare r public.sign_recipients;e public.sign_envelopes;begin
 select * into r from public.sign_recipients where id=recipient;select * into e from public.sign_envelopes where id=r.envelope_id for update;select * into r from public.sign_recipients where id=recipient for update;
 if r.id is null or e.status<>'Sent' or e.expires_at<=now() or r.status in ('Signed','Declined') or r.invited_at>now()-interval '60 seconds' then return false;end if;
 if e.sequential and exists(select 1 from public.sign_recipients where envelope_id=e.id and signing_order<r.signing_order and status<>'Signed') then return false;end if;
 update public.sign_recipients set token_hash=new_token,status='Invited',invited_at=now(),invitation_error=null,session_hash=null,otp_hash=null where id=r.id;return true;end $$;
create function public.sign_request_code(recipient uuid,code_hash text) returns void language plpgsql security definer set search_path='' as $$declare r public.sign_recipients;e public.sign_envelopes;begin
 select * into r from public.sign_recipients where id=recipient;select * into e from public.sign_envelopes where id=r.envelope_id for update;select * into r from public.sign_recipients where id=recipient for update;
 if r.id is null or e.status not in ('Sent','Completing','Completed') or (e.status<>'Completed' and e.expires_at<=now()) or (e.status='Completed' and e.completed_at<now()-interval '90 days') or r.status='Declined' then raise exception 'Signing link is unavailable';end if;
 if e.sequential and exists(select 1 from public.sign_recipients where envelope_id=e.id and signing_order<r.signing_order and status<>'Signed') then raise exception 'Waiting for an earlier signer';end if;
 if r.otp_sent_at>now()-interval '60 seconds' then raise exception 'Wait one minute before requesting another code';end if;
 if r.otp_window_start>now()-interval '1 hour' and r.otp_send_count>=10 then raise exception 'Code request limit reached; try later';end if;
 update public.sign_recipients set otp_hash=code_hash,otp_attempts=0,otp_expires_at=now()+interval '10 minutes',otp_sent_at=now(),otp_send_count=case when otp_window_start>now()-interval '1 hour' then otp_send_count+1 else 1 end,otp_window_start=case when otp_window_start>now()-interval '1 hour' then otp_window_start else now() end where id=r.id;
 insert into public.sign_events(envelope_id,recipient_id,event) values(e.id,r.id,'Email verification code requested');end $$;
create function public.sign_verify_code(recipient uuid,code_hash text,new_session_hash text) returns boolean language plpgsql security definer set search_path='' as $$declare r public.sign_recipients;e public.sign_envelopes;begin
 select * into r from public.sign_recipients where id=recipient;select * into e from public.sign_envelopes where id=r.envelope_id for update;select * into r from public.sign_recipients where id=recipient for update;
 if r.id is null or e.status not in ('Sent','Completing','Completed') or (e.status<>'Completed' and e.expires_at<=now()) or (e.status='Completed' and e.completed_at<now()-interval '90 days') or r.status='Declined' or r.otp_hash is null or r.otp_expires_at is null or r.otp_expires_at<=now() or r.otp_attempts>=5 then return false;end if;
 if r.otp_hash<>code_hash then update public.sign_recipients set otp_attempts=otp_attempts+1 where id=r.id;return false;end if;
 update public.sign_recipients set session_hash=new_session_hash,session_expires_at=now()+interval '1 hour',otp_hash=null,verified_at=case when status='Signed' then verified_at else now() end,status=case when status='Signed' then 'Signed' else 'Viewed' end where id=r.id;
 insert into public.sign_events(envelope_id,recipient_id,event) values(e.id,r.id,'Email verified and signing access granted');return true;end $$;
create function public.sign_submit_values(recipient uuid,session_key text,field_values jsonb,signer_name text,consent text,signer_ip text,signer_agent text,decline text default null) returns uuid language plpgsql security definer set search_path='' as $$declare r public.sign_recipients;e public.sign_envelopes;begin
 select * into r from public.sign_recipients where id=recipient;select * into e from public.sign_envelopes where id=r.envelope_id for update;select * into r from public.sign_recipients where id=recipient for update;
 if r.id is null or r.session_hash is distinct from session_key or r.session_expires_at is null or r.session_expires_at<=now() then raise exception 'Verify your email again';end if;
 if r.status='Signed' then return e.id;end if;
 if e.status<>'Sent' or e.expires_at<=now() then raise exception 'Request is not accepting signatures';end if;
 if e.sequential and exists(select 1 from public.sign_recipients where envelope_id=e.id and signing_order<r.signing_order and status<>'Signed') then raise exception 'Waiting for an earlier signer';end if;
 if decline is not null then update public.sign_recipients set status='Declined',decline_reason=left(decline,2000) where id=r.id;update public.sign_envelopes set status='Declined' where id=e.id;insert into public.sign_events(envelope_id,recipient_id,event,details) values(e.id,r.id,'Declined',jsonb_build_object('reason',decline));return e.id;end if;
 if length(trim(signer_name))=0 or length(consent)=0 then raise exception 'Name and electronic signing consent required';end if;
 update public.sign_recipients set status='Signed',values=field_values,legal_name=trim(signer_name),consent_text=consent,signed_at=now(),ip_address=left(signer_ip,100),user_agent=left(signer_agent,1000) where id=r.id;
 insert into public.sign_events(envelope_id,recipient_id,event,details) values(e.id,r.id,'Signed',jsonb_build_object('legal_name',trim(signer_name),'consent',consent));
 if not exists(select 1 from public.sign_recipients where envelope_id=e.id and status<>'Signed') then update public.sign_envelopes set status='Completing',completed_at=now() where id=e.id;end if;return e.id;end $$;
create function public.sign_void_request(envelope uuid,reason text) returns void language plpgsql security definer set search_path='' as $$declare e public.sign_envelopes;begin
 select * into e from public.sign_envelopes where id=envelope for update;if not found or not public.can_manage_sign_envelope(e) or e.status not in ('Draft','Sent') or length(trim(reason))=0 then raise exception 'Cannot void this request';end if;
 update public.sign_envelopes set status='Voided',void_reason=left(reason,2000) where id=e.id;update public.sign_recipients set session_hash=null,otp_hash=null where envelope_id=e.id;
 insert into public.sign_events(envelope_id,event,actor_id,details) values(e.id,'Voided',auth.uid(),jsonb_build_object('reason',reason));end $$;
grant execute on function public.sign_void_request(uuid,text) to authenticated;revoke all on function public.sign_void_request(uuid,text) from public,anon;
do $$declare f text;begin foreach f in array array['sign_begin_send(uuid,text,text,text,text,jsonb,integer)','sign_claim_invitation(uuid,text)','sign_request_code(uuid,text)','sign_verify_code(uuid,text,text)','sign_submit_values(uuid,text,jsonb,text,text,text,text,text)'] loop execute 'revoke all on function public.'||f||' from public,anon,authenticated';execute 'grant execute on function public.'||f||' to service_role';end loop;end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('signvolt-files','signvolt-files',false,20971520,array['application/pdf']) on conflict(id) do nothing;
create policy sign_file_upload on storage.objects for insert to authenticated with check(bucket_id='signvolt-files' and exists(select 1 from public.sign_envelopes e where public.can_manage_sign_envelope(e) and e.status='Draft' and name like e.user_id::text||'/'||e.id::text||'/draft/%'));
create policy sign_file_read on storage.objects for select to authenticated using(bucket_id='signvolt-files' and exists(select 1 from public.sign_envelopes e where name like e.user_id::text||'/'||e.id::text||'/%'));
commit;
